update public.preguntas set
    explicacion = v.explicacion::text,
    norma = v.norma::text
from (values
('cap-63fba38ee4a8', 'El esfuerzo de frenado que puede aplicar una rueda está directamente relacionado con la carga que soporta. Cuanto mayor es el peso sobre una rueda, mayor es la adherencia disponible entre el neumático y la calzada, lo que permite un mayor esfuerzo de frenado antes de que la rueda bloquee. Las ruedas delanteras o traseras sí influyen en el reparto de pesos, pero no son la causa directa del esfuerzo de frenado. La antigüedad de la rueda no determina el esfuerzo de frenada, sino el estado del neumático.', NULL),
('cap-63fe43a19f7d', 'El sistema TCS, o control de tracción, está diseñado para evitar que las ruedas patinen al acelerar, actuando directamente sobre la fuerza que se transmite a las ruedas. Su objetivo es mejorar la adherencia y la estabilidad del vehículo, especialmente en superficies resbaladizas o al arrancar. No tiene ninguna relación con la dirección de las ruedas motrices, ya que esa es función del sistema de dirección.', NULL),
('cap-64092c782ba5', 'Aprovechar la inercia del vehículo es una técnica de conducción eficiente que permite reducir el consumo de combustible. Al dejar que el vehículo ruede por su propia inercia, se evita acelerar innecesariamente y se minimiza el uso del freno. Esto no solo ahorra carburante, sino que también disminuye el desgaste de los componentes mecánicos. La idea de pasar directamente de acelerar a frenar es ineficiente y aumenta el consumo.', NULL),
('cap-641c0fe0f64f', 'Según la OM 27/07/1999 Art. 2, los vehículos de transporte de mercancías con una MMA superior a 20.000 kg deben llevar dos extintores. Ambos extintores deben ser de la clase 34A/144B. La opción de llevar un solo extintor, o extintores de menor capacidad como el 8A/34B, no cumple con la normativa para este tipo de camión.', 'OM 27/07/1999 Art. 2'),
('cap-642e51ba36d0', 'La parálisis facial no está reconocida como enfermedad profesional en el sector del transporte. El RD 1299/2006 Anexo I clasifica las enfermedades profesionales por grupos de agentes causantes, y la parálisis facial no se incluye en ninguna de esas categorías como enfermedad directamente vinculada a la actividad del transporte. La sordera provocada por el ruido sí es una enfermedad profesional reconocida, ya que el ruido es un agente físico común en el transporte.', 'RD 1299/2006 Anexo I'),
('cap-6467e955a7b1', 'La aerodinámica del vehículo es clave porque una mayor resistencia al aire obliga al motor a trabajar más para mantener la velocidad, aumentando el consumo. Un filtro de aire sucio restringe la entrada de aire al motor, lo que provoca una combustión ineficiente y, por tanto, un mayor gasto de carburante. Los ralentizadores no influyen directamente en el consumo, ya que su función es frenar el vehículo, no propulsarlo.', NULL),
('cap-646f14857ba2', 'El perfil de la carretera, ya sea llano, en subida o en bajada, influye directamente en la resistencia que el motor debe vencer y en la necesidad de retención. Por eso, el conductor debe seleccionar la marcha adecuada para mantener la potencia necesaria o para aprovechar el freno motor. No es correcto pensar que solo afecta en subidas o bajadas, ya que incluso en llano la marcha debe ser la correcta para la velocidad y carga.', NULL),
('cap-64756d8b3ed6', 'La placa TIR es de fondo azul con las letras TIR en blanco. Esta placa identifica claramente al vehículo que realiza un transporte bajo el régimen TIR, facilitando los controles aduaneros. Las opciones que mencionan el mes y año de caducidad son incorrectas, ya que esa información no va en la placa TIR.', 'Convenio TIR Anexo 5'),
('cap-6499df9897c0', 'El saludo es el primer paso fundamental en cualquier interacción profesional, ya que establece un ambiente de respeto y cordialidad. Es la forma básica de iniciar la comunicación y mostrar buena educación. La acreditación de identidad o la entrega de publicidad son acciones posteriores al saludo inicial. Averiguar las intenciones del cliente de entrada es una actitud inapropiada y desconfiada.', NULL),
('cap-64ad64a9b15f', 'La presión de los neumáticos influye directamente en la resistencia a la rodadura, y una presión incorrecta aumenta el consumo. La posición del pedal del acelerador determina la cantidad de combustible inyectado al motor, siendo el factor más directo en el consumo. El motor de arranque y el tipo de ralentizador no tienen un impacto significativo en el consumo habitual del vehículo. La longitud del cigüeñal es una característica fija del motor y no afecta al consumo en el uso diario.', NULL),
('cap-64b274c149ea', 'La zona de consumos específicos mínimos se logra cuando el motor trabaja de forma eficiente, sin ir a tope ni demasiado relajado. Apretar el acelerador al 75% permite al motor desarrollar la potencia necesaria para mover el vehículo de forma óptima, sin un esfuerzo excesivo que aumente el consumo. Si se aprieta al 100%, el motor está forzado y el consumo se dispara. Con el acelerador al 50% o 25%, el motor no está trabajando en su punto más eficiente para el consumo.', NULL),
('cap-64c838600207', 'El intárder es un tipo de retardador hidráulico que se integra directamente en la caja de velocidades o en la transmisión para frenar el vehículo sin usar los frenos de servicio. Su funcionamiento se basa en la resistencia que opone un fluido al movimiento de unas turbinas, disipando energía y ralentizando el giro del árbol de transmisión. Colocarlo en el colector de escape o admisión no tiene sentido, ya que son partes del motor relacionadas con la entrada y salida de gases, no con la transmisión de fuerza. Tampoco va directamente en las pastillas o zapatas de freno, porque es un sistema de frenado auxiliar independiente de los frenos de servicio.', NULL),
('cap-64cb558dc92b', 'La norma general prohíbe al conductor participar en la carga y descarga para evitar riesgos y responsabilidades. Sin embargo, si el vehículo lleva una grúa, el conductor es el operario cualificado para manejarla y, por tanto, sí puede participar en la carga. Los vehículos con regulación de temperatura o los portacontenedores no implican que el conductor deba participar en la carga, ya que no tienen equipos específicos para ello que deba manejar.', NULL),
('cap-64f6cf8bbcdd', 'La formación continua del CAP es única, independientemente de si el conductor realiza transporte de viajeros o de mercancías. El objetivo es actualizar los conocimientos comunes a la profesión, por lo que no es necesario duplicar la formación. Realizar un curso diferenciado para cada categoría de permisos es un error, ya que la normativa establece un único requisito de formación continua para el CAP.', NULL),
('cap-6501086b019b', 'Un aceite de buena calidad, con las propiedades adecuadas, reduce la fricción entre las piezas móviles del motor. Al disminuir los rozamientos internos, el motor necesita menos energía para funcionar, lo que se traduce en un menor consumo de carburante. Los aceites monogrados no son necesariamente mejores para el consumo, ya que su viscosidad es constante y no se adapta a las diferentes temperaturas de funcionamiento como los multigrados. La densidad del aceite no es el factor principal que determina la reducción de rozamientos.', NULL),
('cap-6503e6fcc551', 'En el régimen TIR, las autoridades aduaneras pueden limitar el número de aduanas de salida para controlar mejor el tránsito. El mínimo establecido para estas aduanas de salida es de tres. Esto asegura un equilibrio entre la flexibilidad del transporte y el control aduanero necesario.', NULL),
('cap-650a357c1ad3', 'El Reglamento Comunitario (CE) 561/2006 Art. 10.1 prohíbe expresamente remunerar a los conductores en función de la distancia recorrida si esto puede comprometer la seguridad en carretera o fomentar infracciones. La seguridad es prioritaria y no se puede poner en riesgo por incentivos económicos. La opción de que "sí, siempre que lo crea conveniente" es incorrecta porque la ley establece límites claros a la libertad de la empresa en este aspecto.', 'Reglamento Comunitario (CE) 561/2006 Art. 10.1'),
('cap-6526a8361f0f', 'Un camión con caja abierta o un autobús de dos pisos descubierto presenta una mayor resistencia al aire. Esta mayor resistencia aerodinámica obliga al motor a trabajar más para mantener la velocidad, lo que se traduce en un mayor consumo de carburante. La aerodinámica es peor, no menor, y el peso no es el factor principal que explica el aumento de consumo en este caso.', NULL),
('cap-652ec08d65d3', 'Los tiempos de presencia son aquellos en los que el conductor está a disposición de la empresa pero no realiza trabajo efectivo, como esperas o averías. Según el RD 1561/1995 Art. 8, estos tiempos no pueden superar las 20 horas semanales de promedio en un mes. La opción que indica que pueden prolongarse todo lo que sea necesario es incorrecta, ya que la normativa establece un límite claro para proteger al trabajador.', 'RD 1561/1995 Art. 8'),
('cap-6536953c4859', 'En el motor se producen pérdidas de energía por varias razones. Una parte importante de la energía se pierde en los gases de escape, que salen a una temperatura muy alta. Otra parte se disipa en forma de calor a través del sistema de refrigeración, que mantiene el motor a su temperatura óptima de funcionamiento. Finalmente, también hay pérdidas por el rozamiento entre las diferentes piezas móviles del motor.', NULL),
('cap-653eccc2acdf', 'La regulación del asiento debe hacerse siempre antes de iniciar el recorrido para asegurar una postura correcta y segura desde el primer momento. Ajustar el asiento una vez en marcha es peligroso porque desvía la atención de la conducción. Al finalizar el recorrido no tiene sentido, ya que la postura es importante durante la conducción. No se puede hacer en cualquier momento, ya que hacerlo en marcha es un riesgo.', NULL),
('cap-653f9280e77d', 'Los equipos de protección individual de la totalidad del cuerpo incluyen la ropa de protección contra agresiones químicas y mecánicas, así como los equipos de protección contra caídas en altura. Los arneses son un componente fundamental de los equipos de protección contra caídas en altura. Por lo tanto, todas las opciones mencionadas son correctas al referirse a la protección de la totalidad del cuerpo.', 'RD 773/1997 Anexo I'),
('cap-65473b4d252c', 'En las empresas pequeñas, la plantilla es reducida y cada empleado debe ser más versátil, asumiendo diversas responsabilidades para cubrir las necesidades operativas. Por el contrario, en las empresas grandes hay más especialización de funciones y cada puesto está más definido. Afirmar que el tamaño de la empresa no influye es incorrecto, ya que la estructura organizativa es un factor clave. Decir que el conductor nunca realiza otras tareas es falso, ya que es una práctica común en el sector, especialmente en empresas pequeñas.', NULL),
('cap-65499ed1c168', 'La comodidad es una característica proporcional porque, a mayor comodidad ofrecida en el servicio de transporte, mayor será el nivel de calidad percibido por el cliente. Es una relación directa y escalable. La puntualidad y la seguridad del vehículo son características umbral: se dan por supuestas y su ausencia resta calidad, pero su presencia no aumenta la percepción de calidad más allá de un cierto punto.', NULL),
('cap-65956fa471fe', 'Una alimentación inadecuada, especialmente si es pesada o irregular, puede provocar digestiones lentas y pesadas que restan energía al cerebro, lo que se traduce en una menor capacidad para mantener la atención en la carretera. Esto afecta directamente a la concentración del conductor. Retrasar la aparición del sueño no es un efecto directo de una mala alimentación, sino más bien de estimulantes o falta de descanso.', NULL),
('cap-65a7aa5769c1', 'La energía cinética de un vehículo depende de su masa y de su velocidad. Sin embargo, la velocidad influye mucho más porque su valor se eleva al cuadrado en la fórmula de la energía cinética. Por eso, un pequeño aumento de la velocidad supone un gran incremento de la energía cinética. La aerodinámica o la altura no influyen directamente en la energía cinética, sino en la resistencia al avance o la estabilidad.', NULL),
('cap-65afe26176a3', 'El certificado de actividades es un documento que el conductor entrega a la empresa, no a los agentes de control. Su función es informar a la empresa sobre las actividades realizadas en periodos en los que no ha estado a su disposición, como bajas o vacaciones. Los agentes de control solo necesitan ver los registros del tacógrafo para verificar las actividades del conductor.', NULL),
('cap-65cb8fdf5fc7', 'Los transitarios se dedican a organizar transportes internacionales de mercancías, tal como establece la Ley 16/1987 Art. 121. Su función principal es gestionar todo lo necesario para que la mercancía llegue a su destino en otro país, incluyendo trámites aduaneros y logísticos. No se limitan a cargas completas ni son lo mismo que las agencias TIR. Aunque pueden organizar transportes intermodales, su especialización principal y definitoria es el ámbito internacional.', 'Ley 16/1987 Art. 121'),
('cap-65e050d93545', 'El reposacabezas es un elemento de seguridad pasiva porque su función es proteger al conductor y a los ocupantes una vez que el accidente ya se ha producido, minimizando las lesiones cervicales. Los sistemas como el ASR, el ABS y el control de estabilidad son de seguridad activa, ya que actúan para evitar que el accidente ocurra.', NULL),
('cap-65eee3e4416a', 'El estrés afecta negativamente a la capacidad de concentración y reacción, por lo que es fundamental tomar medidas para garantizar la seguridad. Buscar ayuda profesional es clave para gestionar el estrés a largo plazo. Si es posible, lo mejor es no conducir bajo estrés, pero si no hay alternativa, hay que extremar la precaución al volante.', NULL),
('cap-65fd957073b9', 'Una cisterna que tiene un dispositivo de producción de frío individual para bajar y mantener la temperatura se denomina frigorífica. Este tipo de cisterna está diseñada para mantener una temperatura constante y controlada. La opción que menciona "friogénica" se refiere a cisternas para gases licuados a muy baja temperatura, que no es el caso aquí.', 'Acuerdo ATP Anejo I'),
('cap-660dce98a810', 'Los accidentes con forma no traumática, como los infartos o derrames cerebrales, suelen tener consecuencias más graves y requieren periodos de recuperación más largos. Aunque los accidentes traumáticos pueden ser muy graves, estadísticamente los no traumáticos son los que generan bajas de mayor duración. Los accidentes de origen violento o con un elemento externo son tipos de accidentes que pueden ser traumáticos o no traumáticos, y su duración de baja dependerá de la naturaleza de la lesión.', NULL),
('cap-662a7873b19e', 'Al auxiliar en un accidente, la prioridad es la seguridad de todos, incluyendo la tuya. Usar guantes y mascarillas te protege de posibles contagios por fluidos corporales o enfermedades transmitidas por el aire. Actuar sin estas protecciones, aunque sea rápido, te expone a riesgos innecesarios.', NULL),
('cap-668a310e0a36', 'Las mercancías que están en territorio aduanero de la Unión Europea se presumen de la Unión. Esto significa que, por defecto, se consideran mercancías de la Unión. Sin embargo, esta presunción no es absoluta y se puede demostrar lo contrario. La opción que dice que siempre se consideran mercancías de la Unión es incorrecta porque no contempla la posibilidad de demostrar un estatuto diferente.', 'Reglamento Comunitario (UE) 952/2013 Art. 153'),
('cap-66929bf2b145', 'El Reglamento Comunitario (UE) 952/2013 Art. 6 establece que el intercambio de información entre aduanas y operadores debe ser electrónico. Sin embargo, el mismo artículo contempla excepciones. Se permite usar otros medios si el tipo de tráfico lo justifica o si los sistemas informáticos fallan temporalmente. Por lo tanto, ambas condiciones son excepciones válidas a la regla general del intercambio electrónico.', 'Reglamento Comunitario (UE) 952/2013 Art. 6'),
('cap-66d24e446cf2', 'Las autoridades pueden inmovilizar un vehículo si el incumplimiento de los tiempos de conducción y descanso pone en peligro la seguridad en carretera. Esta medida se toma para subsanar la infracción y garantizar que el conductor pueda descansar adecuadamente antes de continuar. La inmovilización no es una decisión arbitraria, sino que está justificada por el riesgo para la seguridad. La opción de que nunca se puede inmovilizar es incorrecta, ya que la normativa contempla esta posibilidad en situaciones de riesgo.', 'Reglamento Comunitario (CE) 561/2006 Art. 21'),
('cap-66db28aa6d07', 'La Ergonomía busca adaptar el trabajo al trabajador para mejorar su bienestar y eficiencia, lo que incluye el diseño de equipos, el entorno y las posturas. La remuneración es un aspecto económico y de gestión de recursos humanos, no un objetivo directo de la Ergonomía. Diseñar las máquinas y el entorno para la eficacia y la salud son objetivos clave de la Ergonomía.', NULL),
('cap-66ed3f4ab6b0', 'Un cambio de dirección brusco genera fuerzas laterales, también llamadas transversales, que empujan el vehículo hacia los lados. Estas fuerzas pueden superar la adherencia de los neumáticos al asfalto, provocando que el vehículo derrape y el conductor pierda el control. El consumo de combustible no se ve directamente afectado por un cambio de dirección brusco, sino por el estilo de conducción general.', NULL),
('cap-66f1957478e1', 'Una conducción económica implica usar marchas largas, acelerar suavemente y evitar frenazos bruscos. Esto reduce el ruido del motor y de los neumáticos, disminuyendo la contaminación acústica. Aumentar los intervalos de mantenimiento o prolongar los plazos de la ITV son prácticas peligrosas y no tienen relación con la conducción económica.', NULL),
('cap-67366e3fb2bf', 'En la zona intermedia del cuentarrevoluciones, el motor funciona de manera más eficiente porque se logra un equilibrio óptimo entre el combustible inyectado y el aire disponible para la combustión. Esto permite aprovechar al máximo la energía del carburante, lo que se traduce en un menor consumo y una mayor eficiencia. En la zona baja, el motor no tiene suficiente inercia para una combustión eficiente, y en la zona alta, el exceso de revoluciones puede llevar a una combustión incompleta y un mayor desgaste.', NULL),
('cap-673c23dbe9b6', 'El transporte de animales vivos siempre requiere una autorización específica de sanidad animal, además de la autorización de transporte de mercancías que sea necesaria según el tipo de servicio. La autorización genérica de transporte es obligatoria si se superan los límites de MMA o si se realiza transporte público. Pensar que no se necesita autorización genérica porque ya lo controlan las autoridades sanitarias es un error, son autorizaciones distintas y complementarias.', 'RD 751/2006 Art. 6.1'),
('cap-675ecd77a20f', 'El consumo de carburante está directamente relacionado con el número de revoluciones del motor, ya que a más revoluciones, el motor trabaja más y necesita quemar más combustible. Mantener un régimen de revoluciones adecuado es clave para la eficiencia. La situación de las ruedas motrices no influye directamente en el consumo, sino en la tracción. El tipo de freno o el porcentaje de anticongelante no tienen un impacto directo en la cantidad de carburante que consume el motor.', NULL),
('cap-676e028044e5', 'Un motor elástico es aquel que mantiene un par motor elevado y constante en un rango amplio de revoluciones, lo que permite al conductor tener una buena respuesta del motor sin necesidad de cambiar de marcha constantemente. Esto es muy útil en la conducción profesional, ya que facilita la adaptación a diferentes situaciones de carga y terreno. La opción que menciona un motor inelástico es incorrecta porque describe lo contrario, un motor con un rango de par útil muy estrecho.', NULL),
('cap-6795af7904f3', 'Respetar la señalización viaria es fundamental porque estas señales están diseñadas para regular el tráfico y advertir sobre peligros, lo que reduce significativamente el riesgo de accidentes. Al seguir las indicaciones de velocidad, dirección y prohibiciones, se mantiene un flujo seguro y predecible en la carretera. Conducir a una velocidad inadecuada o bajo los efectos del alcohol son comportamientos de alto riesgo que aumentan drásticamente la probabilidad de sufrir un accidente.', NULL),
('cap-67b3f28e5a76', 'La conducción preventiva se basa en anticiparse a los peligros, lo que incluye pensar de forma desconfiada en intersecciones para prever posibles errores de otros conductores. También implica estar preparado para reaccionar rápidamente ante cualquier imprevisto. Además, es fundamental controlar el espacio alrededor del vehículo para tener margen de maniobra y evitar colisiones. Por lo tanto, todas las acciones mencionadas son pilares de la conducción preventiva.', NULL),
('cap-67bb8b935f64', 'El par motor es la fuerza de giro que produce el motor. Se obtiene el par máximo cuando se quema la mayor cantidad de combustible posible con el aire disponible en el cilindro, ya que esto genera la mayor expansión de gases y, por tanto, la mayor fuerza sobre el pistón. Las revoluciones o la velocidad del vehículo son una consecuencia del par, no su causa. El ralentí es un régimen de funcionamiento con muy poco par.', NULL),
('cap-67c83add1624', 'La energía cinética de un camión en movimiento depende directamente de su masa y de la velocidad a la que se desplaza. Cuanto mayor sea la masa o la velocidad, mayor será la energía acumulada. Esto es fundamental para entender las distancias de frenado y la seguridad. La resistencia del aire afecta a la fuerza necesaria para mantener la velocidad, pero no a la energía ya acumulada.', NULL),
('cap-67d51616db11', 'Las zonas sombrías de la carretera son peligrosas porque el sol no las calienta, lo que favorece que el agua se congele y se forme hielo. Esto es especialmente crítico cuando las temperaturas bajan y hay humedad, ya que el hielo es muy difícil de ver y reduce drásticamente la adherencia de los neumáticos. Con niebla densa o viento fuerte, la visibilidad o la estabilidad se ven afectadas en general, no solo en zonas sombrías. Cuando comienza a llover, el peligro principal es la mezcla de agua con suciedad y aceite en el asfalto, no la formación de hielo.', NULL),
('cap-67f0930672db', 'Circular con una presión inferior a la recomendada por el fabricante aumenta la resistencia a la rodadura del neumático. Esta mayor resistencia obliga al motor a trabajar más para mantener la misma velocidad, lo que se traduce en un incremento del consumo de carburante. Una bajada de 2 bares supone un consumo extra de aproximadamente un 2%. La opción que indica que no influye en el consumo es incorrecta, ya que la presión de los neumáticos es un factor clave en la eficiencia del vehículo.', NULL),
('cap-67f447ef537c', 'Una avería mecánica es un incidente porque interrumpe el servicio de transporte sin causar daños graves ni poner en riesgo la vida de los ocupantes. Los otros sucesos, como el incendio, el vuelco o la caída al agua, son accidentes porque implican daños materiales significativos o lesiones personales, lo que los diferencia de un simple incidente.', NULL),
('cap-68000b9b832b', 'El sistema de alimentación es crucial porque es el encargado de suministrar la cantidad adecuada de combustible y aire al motor. Si este sistema no funciona correctamente, la mezcla puede ser demasiado rica o pobre, lo que directamente se traduce en un mayor consumo de carburante. Por ejemplo, un filtro de aire sucio o inyectores defectuosos pueden alterar esta mezcla y aumentar el gasto de combustible. No es cierto que solo influya en la contaminación o la potencia, ya que el consumo es una consecuencia directa de su eficiencia.', NULL),
('cap-683032311e05', 'El BAS detecta cuándo el conductor necesita una frenada de emergencia, aunque no pise el pedal con toda la fuerza necesaria. En ese momento, el sistema aumenta automáticamente la presión de frenado para conseguir la máxima deceleración posible. Esto ayuda a reducir la distancia de frenado en situaciones críticas. Evitar el bloqueo de las ruedas es función del ABS, no del BAS.', NULL),
('cap-688c89ef73ec', 'La Ley 16/1987 Art. 33.4 permite a los inspectores y agentes ordenar el traslado de un vehículo a un taller autorizado si hay indicios fundados de manipulación del tacógrafo o de otros instrumentos de control obligatorios. Esto se hace para verificar la posible infracción. La opción que dice que no se puede ordenar el traslado, solo inmovilizar, es incorrecta porque la ley contempla expresamente el traslado para la verificación.', 'Ley 16/1987 Art. 33.4'),
('cap-688e8b75b4d2', 'La fuerza que se opone al movimiento cuando dos superficies están en contacto, como el neumático y la calzada, se conoce como resistencia por rozamiento o fricción. Esta fuerza es fundamental para que el vehículo pueda avanzar o frenar. El desplazamiento de masas se refiere a cómo el peso del vehículo se distribuye durante el movimiento, no a una fuerza de resistencia.', NULL),
('cap-68a5fd8f6392', 'Los transitarios son empresas que se dedican a organizar transportes internacionales de mercancías, actuando por cuenta ajena. Su función principal es gestionar todo lo necesario para que la mercancía llegue a su destino en otro país, incluyendo trámites aduaneros y logísticos. La Ley 16/1987 Art. 121 define claramente esta actividad. No se limitan a la paquetería o la distribución urbana, ni solo al diseño de rutas intermodales.', 'Ley 16/1987 Art. 121'),
('cap-68cb9c760176', 'El tipo de freno que monte el vehículo no influye en el consumo de carburante porque los frenos solo actúan para detener o reducir la velocidad, no para generar movimiento. La posición del pedal del acelerador, el perfil de la carretera y la presión de los neumáticos sí afectan directamente al esfuerzo que debe hacer el motor y, por tanto, al consumo. Pensar que el tipo de freno influye es un error porque su función es disipar energía, no consumirla para la propulsión.', NULL),
('cap-68dae226858e', 'La resistencia aerodinámica aumenta con el cuadrado de la velocidad, por lo que su influencia en el consumo se vuelve mucho más significativa a velocidades elevadas. A partir de 60 o 70 km/h, el aire ofrece una oposición considerable al avance del vehículo, requiriendo más energía para mantener la velocidad. A velocidades bajas, como menos de 20 km/h, la resistencia aerodinámica es mínima y apenas afecta al consumo.', NULL),
('cap-68dd73de1085', 'Con nieve, es fundamental que el vehículo esté en óptimas condiciones para ver y ser visto, por eso hay que revisar cristales, luces y limpiaparabrisas. También es crucial evitar aceleraciones bruscas para no perder tracción, ya que la adherencia es muy baja. Además, mantener la misma adherencia en todos los neumáticos es vital para la estabilidad y el control del vehículo en estas condiciones tan deslizantes.', NULL),
('cap-690c20ac05e0', 'Circular con el motor a su máxima potencia implica llevarlo a un régimen de revoluciones muy alto, lo que dispara el consumo de combustible. Para ahorrar, hay que buscar un régimen de revoluciones medio, donde el motor es más eficiente. La idea de que un mayor llenado del cilindro o un mejor aprovechamiento del carburante quemado a máxima potencia ahorra combustible es incorrecta, ya que el consumo se prioriza sobre la eficiencia en esas condiciones.', NULL),
('cap-6923c6428845', 'La obligación de auxiliar en un accidente recae sobre todos los usuarios de la vía que lo presencien o tengan conocimiento de él, no solo los implicados. Esto incluye tanto a conductores como a cualquier otro usuario, como peatones o ciclistas. El RD 1428/2003 Art. 129.1 establece claramente esta obligación general de auxilio. No es necesario tener conocimientos acreditados de primeros auxilios para tener esta obligación, basta con solicitar ayuda o colaborar para evitar mayores peligros.', 'RD 1428/2003 Art. 129.1'),
('cap-69405dd9abe6', 'A altas revoluciones, el motor gira muy rápido y el tiempo que la válvula de admisión permanece abierta es muy corto. Esto impide que el cilindro se llene completamente de aire, lo que provoca una combustión incompleta. La inyección de combustible no impide la entrada de aire, ya que son procesos distintos. Tampoco hay una presión excesiva que impida la entrada de aire, ni la válvula de admisión deja de abrirse.', NULL),
('cap-699490a650b5', 'El Reglamento Comunitario (UE) 165/2014 Art. 34.6 detalla qué información debe registrarse obligatoriamente en la hoja de registro del tacógrafo analógico. Entre los datos exigidos están el nombre del conductor, las fechas y lugares de inicio y fin, la matrícula del vehículo y las lecturas del cuentakilómetros. El consumo de combustible no es un dato que el conductor deba anotar obligatoriamente en el disco-diagrama según esta normativa.', 'Reglamento Comunitario (UE) 165/2014 Art. 34.6'),
('cap-69f9bb84823a', 'Los conductores profesionales tienen la tasa más alta de accidentes mortales en comparación con otras ocupaciones. Esto se debe a la exposición constante a riesgos en la carretera, las largas jornadas y la fatiga. Ni los peones de construcción, ni los trabajadores de industrias extractivas, ni los funcionarios de Hacienda superan esta cifra. La creencia de que otras profesiones tienen más riesgo mortal es un error común.', NULL),
('cap-6a09ed415d89', 'Los trabajadores tienen la obligación de utilizar y cuidar correctamente los equipos de protección individual. También deben colocarlos en su sitio después de usarlos. Además, es fundamental que informen a su superior de cualquier defecto que detecten en el equipo. Todas estas acciones son responsabilidades del trabajador según la normativa.', 'RD 773/1997 Art. 10'),
('cap-6a1d5d3f56c5', 'Las hojas de registro están diseñadas con características específicas para cada modelo de tacógrafo analógico, como el rango de velocidad o el tipo de registro. Por eso, cada hoja debe estar homologada para los modelos concretos de tacógrafo con los que es compatible, y esta información debe figurar en la propia hoja. Utilizar una hoja no homologada para el tacógrafo específico puede dar lugar a registros incorrectos o ilegibles. No, las hojas de registro de tacógrafo analógico no sirven para el tacógrafo digital, ya que este último no utiliza hojas.', NULL),
('cap-6a2adaa2b925', 'Los accidentes con forma no traumática, como los infartos o derrames cerebrales, suelen tener consecuencias muy graves y requieren periodos de recuperación prolongados, lo que se traduce en bajas laborales de mayor duración. Las contusiones, rozaduras o intoxicaciones, aunque pueden ser serias, generalmente implican recuperaciones más rápidas. Las intoxicaciones, aunque pueden ser graves, no suelen alcanzar la duración de las bajas por eventos no traumáticos.', NULL),
('cap-6a42e80b8daa', 'El reposacabezas es un elemento de seguridad pasiva porque actúa para reducir las lesiones una vez que el accidente ya se ha producido, minimizando el latigazo cervical. No es un elemento de seguridad activa porque no interviene para evitar el accidente. Tampoco es un elemento de confortabilidad, aunque contribuya a ella, su función principal es la seguridad.', NULL),
('cap-6a47ec07432b', 'El transporte de material de feria está exento del uso de tacógrafo, pero solo si es un transporte privado complementario y el vehículo está específicamente preparado para ello. Así lo establece el RD 640/2007 Art. 2.i. La distancia del trayecto no influye en esta exención, por lo que no hay un límite de kilómetros para que se aplique.', 'RD 640/2007 Art. 2.i'),
('cap-6a59571b1993', 'El Reglamento Comunitario (CE) 1072/2009 Art. 1 establece que este reglamento se aplica a los transportes internacionales de mercancías por carretera por cuenta ajena. Sin embargo, en su apartado 5, exime de la licencia comunitaria y de cualquier autorización de transporte a los transportes de mercancías por cuenta propia que cumplan ciertas condiciones. Por lo tanto, los transportes internacionales de mercancías por cuenta propia dentro de la Unión Europea no necesitan un documento específico que los autorice o certifique. La opción de que se realicen al amparo de una licencia comunitaria es incorrecta porque la licencia comunitaria es para el transporte por cuenta ajena.', 'Reglamento Comunitario (CE) 1072/2009 Art. 1'),
('cap-6a634c5b491e', 'El sistema EBS es un elemento de seguridad activa porque actúa directamente para evitar que se produzca un accidente, mejorando la estabilidad y la eficacia de la frenada. Los elementos de seguridad pasiva, en cambio, están diseñados para minimizar los daños una vez que el accidente ya ha ocurrido. Que un sistema no sea obligatorio no significa que no sea un elemento de seguridad.', NULL),
('cap-6a68c5fa5044', 'En los motores modernos, el sistema de inyección y la electrónica gestionan el arranque de forma óptima sin necesidad de pisar el acelerador. Acelerar durante el arranque solo provoca un consumo extra de combustible sin aportar ninguna ventaja. La idea de que el motor no arranca sin acelerar es un error de los motores antiguos, que no se aplica a los vehículos actuales.', NULL),
('cap-6a7149310298', 'Los vehículos que transportan mercancías peligrosas deben entrar en los núcleos urbanos por el acceso más próximo al punto de entrega para minimizar el tiempo de circulación por zonas pobladas. Esto reduce la exposición al riesgo en caso de accidente. La prohibición total de acceso a núcleos urbanos no es práctica, ya que las mercancías peligrosas a menudo tienen que ser entregadas en estos lugares. No se limita solo a la descarga de clases específicas, ni se restringe únicamente a casos de fuerza mayor.', NULL),
('cap-6a8ca7a8f783', 'El accidente más frecuente al no asegurar la inmovilización del vehículo es que este se desplace sin control y atropelle a alguien. Las caídas de personas, ya sean al mismo o distinto nivel, no son una consecuencia directa de que el vehículo se mueva solo. La exposición a vibraciones es un riesgo relacionado con la conducción, no con el abandono del vehículo sin asegurar.', NULL),
('cap-6b161effbb7e', 'El perfil de la carretera, con sus pendientes y llanos, influye directamente en el esfuerzo que debe hacer el motor. La forma de conducir, anticipando y usando el freno motor, es clave para un consumo eficiente. Además, la aerodinámica del vehículo, es decir, su resistencia al aire, es un factor muy importante que afecta al consumo, especialmente a velocidades altas. Las bujías son para motores de gasolina, no para los diésel de los vehículos pesados.', NULL),
('cap-6b37eba232f1', 'Un camión en movimiento está sometido a múltiples fuerzas como la resistencia del aire, la gravedad, la fricción de los neumáticos y la fuerza del motor. Además, experimenta pares de fuerza que provocan giros, como el par motor o el par de dirección. Estas fuerzas y pares son variables y cambian constantemente según las condiciones de la carretera, la velocidad o las maniobras. No son siempre iguales ni se limitan a fuerzas impares, ya que tanto fuerzas como pares son fundamentales en la dinámica del vehículo.', NULL),
('cap-6b7dd54cff00', 'La primera velocidad está diseñada para arrancar el vehículo y moverlo desde parado. Para ello, el cambio de marchas reduce mucho las revoluciones del motor, lo que se traduce en una gran fuerza en las ruedas, aunque la velocidad sea muy baja. La opción que dice que no hay desmultiplicación es incorrecta, ya que todas las marchas, excepto la directa, implican una desmultiplicación o multiplicación.', NULL),
('cap-6b84aada6274', 'Un motor es elástico cuando entrega su máxima fuerza, o par motor, en un rango amplio de revoluciones. Esto permite al conductor mantener la marcha engranada durante más tiempo sin necesidad de cambiar de velocidad, lo que facilita la conducción y reduce el consumo. Que un motor pueda alcanzar muchas revoluciones no lo hace elástico, ya que podría no tener fuerza en ese rango.', NULL),
('cap-6b861d85c5d5', 'Para la distribución y reparto de mercancías peligrosas a sus destinatarios finales, se debe priorizar el recorrido de la mínima distancia posible por carreteras convencionales. Esto se debe a que las carreteras convencionales suelen tener menos restricciones de acceso para este tipo de vehículos en zonas urbanas o de reparto. Las autovías y autopistas, aunque más rápidas, a menudo no permiten el acceso directo a los puntos de entrega finales, obligando a desvíos o a la entrada en vías convencionales para completar el reparto. La idea de que no hay normativa al respecto es incorrecta, ya que existen regulaciones específicas para el transporte de mercancías peligrosas.', NULL),
('cap-6bb9f1d954fd', 'La energía cinética es la energía que tiene un cuerpo por el hecho de estar en movimiento. Esta energía depende directamente de la masa del vehículo y de su velocidad. Por lo tanto, cuanto mayor sea la masa del vehículo, mayor será su energía cinética. Que la masa sea menor, o que la altura sea mayor o menor, no aumenta la energía cinética.', NULL),
('cap-6bbc0918fd45', 'El documento de control administrativo debe reflejar la identificación de la autorización especial de circulación cuando el transporte la requiera, ya que es un requisito indispensable para ese tipo de servicio. La identificación del conductor es un dato que se registra en el tacógrafo, no en el documento de control administrativo. La identificación del consignatario es un dato que aparece en el contrato de transporte o en el CMR, no en el documento de control administrativo.', NULL),
('cap-6bca07a85bdd', 'Las molestias en la espalda son las más comunes entre los conductores profesionales debido a las vibraciones constantes del vehículo y a la postura sedentaria prolongada. Estas condiciones someten la columna vertebral a un estrés continuo. Ajustar correctamente el asiento y hacer pausas activas son medidas clave para prevenir este tipo de lesiones. Las molestias en las piernas, caderas o brazos son menos frecuentes, aunque también pueden aparecer por una mala ergonomía o falta de movimiento.', NULL),
('cap-6c02aab3040d', 'El ralentizador eléctrico funciona generando un campo magnético que se opone al movimiento de un disco o rotor, creando así una fuerza de frenado sin contacto físico. Este sistema transforma la energía cinética del vehículo en energía eléctrica, que luego se disipa en forma de calor. La opción que menciona el frotamiento es incorrecta porque los ralentizadores eléctricos no utilizan fricción para frenar.', NULL),
('cap-6c1ec34656a0', 'Los fuegos de clase B son los que involucran líquidos o sólidos licuables, como grasas, aceites, pinturas o ceras. Un producto sólido licuable, al calentarse, se convierte en un líquido inflamable, por lo que su comportamiento es el de un fuego de líquidos. Los fuegos de clase A son para combustibles sólidos que no se licúan, como madera o papel.', NULL),
('cap-6c32f3d1edde', 'Las infracciones muy graves contra la normativa de extranjería se sancionan con una multa económica. Según la Ley Orgánica 4/2000 Art. 55, las infracciones muy graves tienen una multa que va desde los 10.001 hasta los 100.000 euros. Las penas de privación de libertad no son una sanción administrativa para este tipo de infracciones. El embargo de flotas de vehículos no es la sanción principal, aunque sí se contempla el decomiso del medio de transporte en casos específicos de infracciones muy graves.', 'Ley Orgánica 4/2000 Art. 55'),
('cap-6c57f43ee1ac', 'Un torno es una herramienta fundamental en la estiba para asegurar la carga. Su función principal es tensar las cinchas o cables que sujetan la mercancía, garantizando que esta quede firmemente inmovilizada y no se desplace durante el transporte. Esto es crucial para la seguridad vial y para evitar daños a la carga. La opción de subir o bajar la mercancía se refiere a un polipasto o grúa, no a un torno de estiba.', NULL),
('cap-6c6a7799dbf6', 'El dióxido de carbono es el elemento más utilizado para extinguir fuegos por sofocación, ya que desplaza el oxígeno del aire, impidiendo la combustión. El nitrógeno también actúa por sofocación, pero es menos común en extintores portátiles. El litio y el ácido sulfúrico no se usan para extinguir fuegos por eliminación de oxígeno.', NULL),
('cap-6cbdd8cf7dac', 'Las Juntas Arbitrales de Transporte están compuestas por representantes de los cargadores y usuarios, de las empresas de transporte y de la Administración Pública. Esta composición asegura que todos los intereses implicados en el transporte de mercancías estén representados. De esta forma, se garantiza una resolución de conflictos equilibrada e imparcial.', NULL),
('cap-6ce97f5ec18a', 'La inclinación del terreno afecta al movimiento del vehículo porque la gravedad tira de él. Cuanta más masa tenga el camión, mayor será la fuerza de la gravedad que actúe sobre él, lo que influirá más en su aceleración o deceleración en una pendiente. La velocidad del camión no es un factor que determine cómo la inclinación afecta al movimiento, sino una consecuencia de esa interacción.', NULL),
('cap-6ceb8d260c43', 'La exposición a sustancias tóxicas se produce cuando no se usan los equipos de protección individual (EPI) necesarios al manipular la mercancía. Estos equipos están diseñados para proteger al trabajador del contacto directo con el producto. El uso de recipientes en buen estado o el llenado a la capacidad correcta son medidas de seguridad, no causas de exposición. Trabajar en recintos abiertos no elimina el riesgo si se manipulan sustancias tóxicas sin protección.', NULL),
('cap-6cf175b42806', 'Refrigerar la zona quemada con agua fría es crucial para detener la progresión de la quemadura y aliviar el dolor. El frío ayuda a reducir la temperatura de la piel y los tejidos subyacentes, minimizando el daño. Romper las ampollas o retirar la ropa quemada puede empeorar la lesión y aumentar el riesgo de infección. Aplicar pomadas no es lo primero que hay que hacer, ya que puede dificultar la valoración médica posterior.', NULL),
('cap-6cf69f24116e', 'Los accidentes de trabajo con forma no traumática son aquellos que no se producen por un golpe o una lesión externa. Tanto los derrames cerebrales como los infartos son eventos de salud que, aunque pueden estar relacionados con el trabajo, no implican un traumatismo directo. Las lumbalgias, por el contrario, suelen ser el resultado de un esfuerzo físico o una mala postura, lo que las clasifica como lesiones musculoesqueléticas, es decir, de origen traumático o por sobreesfuerzo.', NULL),
('cap-6cf87a69566b', 'No es obligatorio que una cisterna tenga rompeolas. Los rompeolas son un elemento de seguridad que ayuda a estabilizar la carga líquida y evitar el efecto de las olas dentro del depósito, pero su instalación no es una exigencia legal. La capacidad de la cisterna o el tipo de líquido transportado no determinan la obligatoriedad de llevar rompeolas.', NULL),
('cap-6cfc498fca28', 'El sistema IHC, o control inteligente de luces de carretera, se encarga de gestionar automáticamente las luces largas. Detecta la presencia de otros vehículos, ya sea por sus faros delanteros o sus luces traseras, y cambia entre luces de carretera y de cruce para no deslumbrar. La opción de que adapta la velocidad manteniendo la distancia de seguridad se refiere al control de crucero adaptativo, que es un sistema diferente. Tampoco tiene que ver con la suspensión ni con la corrección de trayectoria.', NULL),
('cap-6d2f4bd27a31', 'Observar el entorno es fundamental para anticipar peligros y reaccionar a tiempo, lo que permite una conducción preventiva y segura. Esto incluye mirar lejos, cerca y por los retrovisores para tener una visión completa de lo que ocurre alrededor del vehículo. Vigilar el tráfico hasta la distancia en la que se encontrará el vehículo en un par de minutos es excesivo y poco práctico, ya que las condiciones del tráfico cambian constantemente. Ejecutar las maniobras bruscamente es peligroso porque puede desestabilizar el vehículo y sorprender a otros conductores. No advertir las maniobras es un error grave, ya que la comunicación con otros usuarios es clave para la seguridad vial.', NULL),
('cap-6d37d46e7dd8', 'La declaración amistosa de accidente no tiene como objetivo principal ni directo la disminución de los atascos de tráfico. Su función es documentar el siniestro para las aseguradoras. Aunque retirar los vehículos de la calzada puede ayudar a la fluidez, no es el propósito de la declaración en sí. La declaración amistosa de accidente no determina la responsabilidad del siniestro, solo recoge los datos para que las aseguradoras la valoren.', 'Convenio CIDE Art. 4'),
('cap-6d7093391249', 'Los accidentes con vehículos pesados ocurren con mayor frecuencia en carreteras convencionales porque son las vías con más intersecciones, cruces al mismo nivel, curvas cerradas y cambios de rasante, lo que aumenta la complejidad de la conducción. Además, en estas vías se comparten carriles con otros usuarios más vulnerables y se realizan más maniobras como adelantamientos o giros. La opción de que se producen mayoritariamente en zonas urbanas es incorrecta, ya que, aunque hay tráfico denso, las velocidades son bajas y las distancias de seguridad suelen ser mayores.', NULL),
('cap-6d88a20b3e59', 'Bajar una pendiente con el motor parado es una medida equivocada porque anula la dirección asistida y el servofreno, lo que compromete gravemente la seguridad al perder el control del vehículo. Además, el motor parado no consume combustible, pero tampoco genera retención, lo que obliga a un mayor uso de los frenos de servicio. Aprovechar la inercia del vehículo es una técnica de conducción eficiente, pero siempre con el motor en marcha y una marcha engranada para mantener el control y la seguridad.', NULL),
('cap-6dbce9b88230', 'La minoración superior al 50% de los tiempos de descanso semanal obligatorios se considera una infracción muy grave. Esto es así porque la Ley 16/1987, en su Artículo 140.37, tipifica específicamente esta conducta como muy grave. No se considera una infracción leve, grave o que no sea infracción, ya que el incumplimiento de los tiempos de descanso es un asunto serio que afecta directamente a la seguridad vial y a las condiciones laborales del conductor.', 'Ley 16/1987 Art. 140.37'),
('cap-6dd165eb6a1d', 'Para una reanimación boca a boca efectiva, es fundamental colocarse de rodillas junto al herido para tener una posición estable y cómoda. Después de coger aire, se debe soplar en la boca del herido para insuflar aire en sus pulmones. Tras cada insuflación, hay que retirar la boca para permitir que el aire salga de los pulmones del herido y repetir el ciclo. Todas estas acciones son pasos esenciales y consecutivos en la técnica de respiración boca a boca.', NULL),
('cap-6dfe1a0dff19', 'La licencia comunitaria para el transporte de mercancías tiene un plazo de validez máximo de diez años. Este periodo permite una gestión administrativa eficiente sin tener que renovar el documento con demasiada frecuencia. Un plazo indeterminado no es posible porque la administración necesita revisar periódicamente que se siguen cumpliendo las condiciones para su otorgamiento.', NULL),
('cap-6e07230b9fa0', 'Las pantallas de soldadura están diseñadas específicamente para proteger los ojos y la cara del soldador de las chispas, la radiación ultravioleta e infrarroja, y los metales fundidos. Su función principal es la de barrera física y filtro óptico para estas partes del cuerpo. Los protectores de las vías respiratorias son para evitar la inhalación de humos o gases, no para la protección facial directa. Los protectores de pies y piernas o del tronco no tienen relación con la función de una pantalla de soldadura.', 'RD 773/1997 Anexo I'),
('cap-6e0c48b0ed50', 'Una iluminación adecuada permite ver claramente el entorno y la carga, lo que facilita la anticipación de obstáculos y la realización de movimientos precisos, reduciendo así el riesgo de tropiezos, golpes o caídas. Por el contrario, un espacio de trabajo reducido, un suelo resbaladizo o la existencia de vibraciones son factores que aumentan significativamente el riesgo de accidentes y lesiones al manipular cargas.', NULL),
('cap-6e1ebc98a109', 'Las horas de conducción individual se suman de los diferentes módulos del Anexo I del RD 1032/2007. En la modalidad ordinaria, el módulo 1.1 requiere 5 horas, el 1.2 otras 10 horas y el 1.3 otras 5 horas, lo que suma un total de 20 horas. Para la modalidad acelerada, la duración de cada módulo se reduce a la mitad, por lo que serían 10 horas de conducción individual. La opción que indica 25 horas en la modalidad ordinaria es incorrecta porque suma horas de aula como si fueran de conducción efectiva.', 'RD 1032/2007 Anexo I'),
('cap-6e3336418344', 'La Ley 16/1987, en su Artículo 46, establece claramente que para cumplir el requisito de capacidad financiera se deben disponer de 9.000 euros por el primer vehículo. Además, se requieren 5.000 euros adicionales por cada vehículo extra que se utilice. La opción que indica 5.000 euros por el primer vehículo y 9.000 más por cada vehículo adicional es incorrecta, ya que invierte las cantidades establecidas por la normativa para el primer vehículo y los adicionales.', 'Ley 16/1987 Art. 46'),
('cap-6e373573cd65', 'La moqueta es el único tipo de suelo de los propuestos que, por su composición y textura, tiene la capacidad de comprimirse ligeramente. Esta característica le permite absorber y distribuir parte del impacto del peso corporal, ofreciendo una amortiguación. El cemento y el asfalto son superficies rígidas que no ofrecen ninguna capacidad de absorción o amortiguación.', NULL),
('cap-6e3cc7913b76', 'El Acuerdo ATP se aplica a los transportes internacionales de mercancías perecederas que se realicen entre países que hayan firmado este acuerdo. Su objetivo es garantizar que estas mercancías se mantengan en condiciones adecuadas durante el transporte transfronterizo. No se aplica a cualquier transporte de perecederas, sino específicamente a los que cruzan fronteras entre estados adheridos al ATP. Tampoco se limita a la duración del transporte ni a un recorrido mínimo en el ámbito nacional.', 'Acuerdo ATP Introducción'),
('cap-6e4041165906', 'Ninguna de las acciones propuestas previene el sueño de forma efectiva. Poner la radio más fuerte o tomar mucho café son soluciones temporales que no eliminan la causa del sueño y pueden incluso enmascarar la fatiga. Comer copiosamente antes de conducir puede provocar somnolencia, ya que el cuerpo dedica energía a la digestión. La única forma de prevenir el sueño es descansar adecuadamente antes de iniciar el viaje y hacer pausas regulares.', NULL),
('cap-6e88813d58c8', 'Cuando un único contrato con el cargador implica a varios porteadores que se suceden en el transporte, se denomina transporte sucesivo. La Ley 15/2009 Art. 64 describe precisamente esta situación, donde varios porteadores asumen la responsabilidad de trayectos parciales bajo un mismo contrato. La opción de transporte multimodal no es correcta porque implica el uso de diferentes modos de transporte, no necesariamente varios porteadores del mismo modo. Tampoco es un transporte extensivo o conjunto, ya que esos términos no describen esta estructura contractual específica.', 'Ley 15/2009 Art. 64'),
('cap-6e9b51a5524d', 'Las operaciones de carga y descarga son un momento crítico donde ocurren muchos accidentes, ya que implican manipulación de la mercancía, uso de maquinaria y coordinación con otras personas. Mantener la precaución en estas tareas es fundamental para la seguridad. Aunque el mantenimiento de posturas sedentarias es un riesgo para la salud, no es una tarea distinta de la conducción que requiera precaución en el mismo sentido que la carga y descarga.', NULL),
('cap-6ebd8ea76b29', 'En una colisión frontal, el vehículo se detiene bruscamente, pero los ocupantes, por inercia, tienden a seguir moviéndose a la velocidad que llevaban, siendo proyectados hacia delante. El cinturón de seguridad es fundamental para retenerlos y evitar que impacten contra el salpicadero o el parabrisas. Un alcance, por el contrario, proyectaría a los ocupantes hacia atrás.', NULL),
('cap-6ec353fe4da8', 'La mejor postura de trabajo es la que permite la mayor eficacia con la menor fatiga posible, no con la máxima. Una postura inadecuada o la falta de alternancia entre estar sentado y de pie son factores que contribuyen a la fatiga y pueden causar problemas de salud. Es un error pensar que la eficacia debe ir de la mano de la máxima fatiga.', NULL),
('cap-6ed5d5eab626', 'En el transporte de animales vivos, es fundamental llevar a bordo la documentación que acredite la propiedad de los animales, su origen y la autorización del medio de transporte. Estos documentos son esenciales para garantizar la trazabilidad, el bienestar animal y el cumplimiento de la normativa específica. La ausencia de cualquiera de ellos puede acarrear sanciones importantes.', NULL),
('cap-6edbcb5a5ed7', 'Evitar que el motor esté al ralentí durante mucho tiempo es crucial porque, aunque el vehículo no se mueva, el motor sigue consumiendo carburante. Cada minuto al ralentí es un gasto innecesario de combustible. Conducir con un vehículo muy potente no garantiza la optimización del consumo, ya que depende más del estilo de conducción. Circular en punto muerto no es eficiente ni seguro, y circular siempre en marchas cortas fuerza el motor y aumenta el consumo.', NULL),
('cap-6ef7a6774ffd', 'El Acuerdo ATP se aplica a los transportes marítimos si el trayecto es inferior a 150 kilómetros y la mercancía viaja en el mismo vehículo terrestre. Esto es así porque el Acuerdo ATP, en su Artículo 3.2, busca regular el transporte terrestre de mercancías perecederas. La opción que menciona 1.500 kilómetros es incorrecta, ya que el límite para la aplicación del ATP en trayectos marítimos es de 150 kilómetros. Tampoco se aplica a todos los medios de transporte ni a los aéreos, ya que su ámbito es el transporte terrestre y los trayectos marítimos cortos como excepción.', 'Acuerdo ATP Art. 3.2'),
('cap-6f1353ee6433', 'El plazo máximo para comunicar un siniestro es de siete días desde que se tiene conocimiento, según establece la Ley 50/1980 Art. 16. Es importante cumplir este plazo para evitar problemas con la aseguradora. Si se comunica más tarde, la aseguradora podría reclamar daños y perjuicios. Confundir este plazo con treinta o veinte días es un error común, pero la ley es clara al fijar siete días.', 'Ley 50/1980 Art. 16'),
('cap-6f1416395800', 'Es recomendable parar cada dos horas para estirar las piernas y despejar la mente, lo que ayuda a mantener la concentración y reducir el riesgo de fatiga al volante. Parar cada 30 minutos es excesivo y no permite un avance eficiente en el viaje. Detenerse cada 4 o 5 horas es demasiado tiempo sin descanso y aumenta significativamente el riesgo de sufrir fatiga, lo que puede ser muy peligroso.', NULL),
('cap-6f246e7b854b', 'Sí, la velocidad influye directamente en el consumo. A mayor velocidad, el vehículo tiene que vencer una resistencia al aire mucho mayor, lo que exige más potencia del motor y, por tanto, más combustible. La idea de que solo influye a partir de 100 km/h es incorrecta, ya que la resistencia aerodinámica aumenta progresivamente con la velocidad desde el primer momento.', NULL),
('cap-6f6c5f912f4f', 'Conducir a un régimen medio de revoluciones es más eficiente porque el motor no necesita inyectar tanto combustible para mantener esa velocidad, lo que reduce el consumo. El par motor, sin embargo, no tiene por qué disminuir, ya que el par máximo se suele alcanzar a un régimen medio de revoluciones, no al máximo. Por lo tanto, no es correcto afirmar que disminuyen tanto el consumo como el par motor.', NULL),
('cap-6f6fd148be4e', 'El deterioro de la movilidad, como la disminución de la agilidad y el equilibrio, afecta principalmente a los mayores, haciéndolos más vulnerables como peatones. Los niños y los jóvenes, por lo general, tienen una buena movilidad, aunque puedan carecer de experiencia o percepción del riesgo. Los conductores noveles son un grupo de riesgo al volante, no por su movilidad como peatones.', NULL),
('cap-6f714c707461', 'El vehículo jaula está diseñado específicamente para el transporte de animales vivos, ya que su estructura permite la ventilación y el bienestar de los animales durante el trayecto. Las jaulas evitan que los animales se escapen y facilitan su carga y descarga. Transportar mercancías peligrosas en un vehículo jaula sería un grave error, ya que requieren contenedores herméticos y condiciones de seguridad muy diferentes.', 'RD 2822/1998 Anexo II, C'),
('cap-6f91f5ffe17a', 'Desde el motor hasta las ruedas, el sistema de transmisión reduce las revoluciones del motor para aumentar el par motor. Esta reducción de revoluciones es lo que se conoce como desmultiplicación. La multiplicación de revoluciones no es el objetivo principal en la transmisión para mover el vehículo, y la desclasificación o potenciación no son términos técnicos aplicables a este proceso.', NULL),
('cap-6f96ad0637fd', 'Cuando el consignatario no está y el cargador no da instrucciones, el porteador puede solicitar el depósito de la carga ante la Junta Arbitral del Transporte. Esto le libera de sus obligaciones de entrega, ya que el transporte se considera terminado. La opción de devolver la mercancía al cargador no es la correcta, ya que el porteador no tiene esa obligación y podría incurrir en más gastos.', 'Ley 15/2009 Art. 44'),
('cap-6fa1e7593af6', 'Las opciones presentadas describen ventajas del transporte por carretera o desventajas del ferrocarril, pero las formulan como si fueran ventajas del ferrocarril o desventajas de la carretera. El transporte ferroviario es menos flexible en el servicio puerta a puerta y sus trámites suelen ser más complejos. Además, la fiabilidad y previsibilidad del tiempo de tránsito no siempre son superiores al transporte por carretera, especialmente en distancias cortas o medias.', NULL),
('cap-6fb36957310d', 'El número de revoluciones del motor es el factor más directo que influye en el consumo de carburante, ya que a más revoluciones, más combustible se inyecta para mantener ese régimen. Conducir en la zona de par máximo del motor, que suele ser a revoluciones medias, es lo más eficiente. La presión del sistema neumático de frenos no tiene un impacto directo en el consumo de carburante, ya que su función es frenar, no propulsar el vehículo. El tipo de neumático (con cámara o sin cámara) no es un factor determinante en el consumo, lo importante es la resistencia a la rodadura del neumático.', NULL),
('cap-6fc400b98ada', 'El par motor es la fuerza de giro que el motor es capaz de generar. Cuanto mayor sea el par, mayor será la capacidad del motor para mover el vehículo o superar resistencias. La potencia máxima, en cambio, es el resultado de multiplicar el par por las revoluciones, indicando la rapidez con la que se puede realizar un trabajo. El trabajo máximo no es un término técnico que defina esta característica del motor.', NULL),
('cap-6fdd30af6c75', 'Los autobuses de transporte escolar son los vehículos que menos accidentes sufren porque están sometidos a normativas de seguridad muy estrictas y a revisiones técnicas más frecuentes. Además, sus conductores tienen una formación específica y deben cumplir con límites de velocidad más reducidos. Los vehículos articulados y los camiones de más de 3.500 kg, por su tamaño y peso, tienen una mayor probabilidad de verse involucrados en accidentes.', NULL),
('cap-6ff634e71e6f', 'Las carreteras multicarril son vías con al menos dos carriles para cada sentido de circulación, siempre que no sean autopistas, autovías o vías para automóviles. Por lo tanto, ni las autopistas ni las autovías, por sí solas o juntas, definen una carretera multicarril. Es un tipo de vía distinto con sus propias características.', NULL),
('cap-6ffff2e7c3c5', 'La combustión del carburante en el motor genera una expansión de gases que empuja los pistones. Este movimiento lineal se convierte en movimiento rotatorio del cigüeñal, que es la energía mecánica que impulsa el vehículo. La energía electrotérmica no es el resultado principal, y la energía potencial se relaciona con la altura o posición, no con la combustión. La inercia dinámica es una propiedad del movimiento, no una forma de energía en la que se transforme el carburante.', NULL),
('cap-7024c7598359', 'La potencia del motor es la capacidad que tiene para generar trabajo, y depende de factores internos como la cilindrada, la relación de compresión y el número de revoluciones. La aerodinámica es una fuerza externa que se opone al movimiento del vehículo, pero no influye en la potencia que el motor es capaz de desarrollar. La cilindrada, la relación de compresión y el número de revoluciones son características constructivas y de funcionamiento del motor que sí determinan su potencia.', NULL),
('cap-704d68a61c1a', 'El par motor es la fuerza de giro que produce el motor. Al ralentí, el motor gira a las mínimas revoluciones posibles sin calarse, lo que significa que está produciendo la menor fuerza de giro. A medida que aumentan las revoluciones, el motor es capaz de generar más par. La opción de que el par mínimo se produce al máximo de revoluciones es incorrecta, ya que a ese régimen el motor está entregando su máxima potencia y, por tanto, un par elevado.', NULL),
('cap-70a17e69b58f', 'Es fundamental comprobar los frenos al salir de una zona inundada porque el agua puede reducir su eficacia, mojando las pastillas y los discos. Una frenada suave y progresiva al salir de la zona ayuda a secarlos y a recuperar su rendimiento. Pasar en una marcha larga como la quinta no es lo adecuado, ya que se necesita más control y fuerza en el motor para evitar que el vehículo se cale. Frenar bruscamente dentro del agua es peligroso porque puede provocar un aquaplaning o la pérdida de control del vehículo.', NULL),
('cap-70ad8f99d5a4', 'El perfil de la carretera, la posición del acelerador y la marcha seleccionada son factores directos que influyen en la carga del motor y, por tanto, en el consumo de combustible. Una pendiente ascendente exige más energía, al igual que una mayor apertura del acelerador o una marcha inadecuada. El material de la carrocería afecta al peso total, pero no es un factor directo en el consumo energético del motor en un momento dado.', NULL),
('cap-70da9c931e09', 'Cuando se inyecta la máxima cantidad de carburante que se puede quemar con el aire disponible en el cilindro, se logra la combustión más eficiente para generar fuerza de giro. Esta fuerza es el par motor, y en ese punto se alcanza su valor máximo. El par máximo es crucial para la capacidad de arrastre y aceleración del vehículo, no para la velocidad máxima ni las revoluciones máximas.', NULL),
('cap-710815597b13', 'El contacto de la carga del vehículo con tendidos eléctricos es extremadamente peligroso porque la electricidad busca el camino más corto a tierra a través del vehículo y de la persona que lo manipula, provocando una descarga de alto voltaje. Esta descarga causa paradas cardíacas y la muerte de forma casi instantánea. La no utilización de elementos de protección, aunque grave, no es la causa más frecuente de paradas cardíacas y muerte en el transporte.', NULL),
('cap-7138129be9f0', 'Los transportes de mercancías de carácter privado complementario, realizados por empresas agrícolas dentro de un radio de 100 kilómetros alrededor de su centro de explotación, están exentos de llevar tacógrafo. Esta exención está recogida específicamente en el RD 640/2007 Art. 2.e. No deben llevar un tacógrafo especial, ni digital, ni analógico, ya que la normativa los exime completamente de su uso en estas condiciones.', 'RD 640/2007 Art. 2.e'),
('cap-7139c26b4b0b', 'En una sociedad de responsabilidad limitada, todos los socios tienen derecho a asistir a la junta general, independientemente del número de participaciones que posean. Este derecho es fundamental para que puedan participar en las decisiones importantes de la empresa. La asistencia no depende de lo que digan los estatutos ni de lo que se especifique en la convocatoria, ya que es un derecho básico e irrenunciable de todo socio. La idea de que se necesita un mínimo de participaciones es un error, ya que ese requisito es más propio de las sociedades anónimas.', NULL),
('cap-715be0a314c2', 'El tacógrafo digital se activa al insertar por primera vez una tarjeta de centro de ensayo. Esta tarjeta es la que permite calibrar y configurar el tacógrafo antes de su uso. La activación no ocurre cuando el taller le da corriente, ya que necesita una configuración inicial específica. Tampoco se activa en la fábrica, ni al insertar una tarjeta de empresa, que solo se usa para gestionar los datos una vez el tacógrafo ya está operativo.', 'Reglamento Comunitario (UE) 165/2014 Anexo IB, apartado V, 1 (3821/85)'),
('cap-7166036c8179', 'Las baterías de litio son las que ofrecen mayor autonomía en los vehículos eléctricos porque tienen una densidad energética superior, lo que significa que pueden almacenar más energía en menos espacio y peso. Esto se traduce directamente en una mayor distancia que el vehículo puede recorrer con una sola carga. Las baterías de níquel, cadmio o cobalto no alcanzan el mismo rendimiento en este aspecto.', NULL),
('cap-7172318a68aa', 'Para reducir la resistencia a la pendiente, el conductor debe anticiparse y seleccionar la marcha adecuada antes de que el camión pierda inercia. Esto permite mantener un régimen de revoluciones constante y evitar que el motor se "ahogue". Realizar menos cambios de marcha en la pendiente ayuda a mantener la fuerza de tracción de manera más continua y eficiente. Aumentar el número de cambios de marcha es un error porque cada cambio interrumpe la fuerza de tracción y hace que el vehículo pierda velocidad.', NULL),
('cap-71a013e7f2ed', 'La baja estatura de los niños es la principal causa de riesgo porque les impide ver bien el tráfico y, a la vez, hace que sean menos visibles para los conductores, especialmente detrás de obstáculos o vehículos aparcados. Su campo visual limitado les dificulta anticipar peligros. Pensar que tienen una alta concentración es un error, ya que su atención es muy variable y se distraen fácilmente.', NULL),
('cap-71a6bebdee57', 'Las operaciones ordinarias de contabilidad, como registrar facturas o gestionar pagos, son tareas administrativas. El administrativo es el profesional encargado de la gestión documental y económica de la empresa. El conductor se centra en la conducción y entrega, mientras que el comercial se dedica a la venta y el jefe de tráfico a la planificación de rutas.', NULL),
('cap-71af424eee21', 'El sistema avanzado de frenado de emergencia está diseñado para detectar situaciones de riesgo de colisión frontal y actuar automáticamente. Su función principal es iniciar una frenada de emergencia para mitigar o evitar el impacto cuando el conductor no reacciona a tiempo. No se encarga de evitar la pérdida de adherencia por aceleración brusca, ya que esa es la función del control de tracción. Tampoco equilibra la acción del freno sobre cada rueda, que es tarea del repartidor de frenada, ni evita el bloqueo de las ruedas, que es la función del ABS.', NULL),
('cap-71d0b389a8d0', 'El peaje se cobra por el uso de una infraestructura específica, por lo que su cálculo debe basarse en los costes directos de ese tramo de carretera. Incluir costes de otros tramos o de toda la red, incluso los no afectados por el peaje, no tiene sentido porque el usuario paga por lo que utiliza. Los costes de inversión en otros tramos no deben repercutirse en un peaje concreto.', NULL),
('cap-71f71bac5890', 'Las cajas de cambio automático suelen tener un consumo de carburante mayor porque el convertidor de par, que es un elemento clave en su funcionamiento, genera pérdidas de energía por deslizamiento. Además, la gestión electrónica del cambio automático puede no ser siempre tan eficiente como un conductor experimentado que selecciona la marcha óptima manualmente. Las cajas con cambio sincronizado, por el contrario, son un tipo de caja manual y no tienen este problema de pérdidas por deslizamiento.', NULL),
('cap-720ad3d6953f', 'El descanso diario normal de 11 horas consecutivas es el único que no tiene limitaciones en cuanto a cuántas veces se puede realizar. El Reglamento Comunitario (CE) 561/2006 Art. 8.4 establece que solo se pueden tomar hasta tres descansos diarios reducidos entre dos descansos semanales. Un descanso de 5 horas no existe como tipo de descanso diario reglamentario. La afirmación de que no se puede realizar el mismo tipo de descanso diario de modo consecutivo es incorrecta, ya que el descanso normal sí se puede repetir.', 'Reglamento Comunitario (CE) 561/2006 Art. 8.4'),
('cap-720aeb79989e', 'El permiso de conducción es un documento personal e intransferible que acredita que estás autorizado para conducir el vehículo. Es obligatorio llevarlo siempre a bordo para poder identificarte y demostrar tu habilitación ante cualquier control. No importa el tipo de vehículo ni la antigüedad de tu permiso, la obligación es la misma. La idea de que solo es necesario en vehículos pesados o ligeros es incorrecta, ya que la normativa aplica a todos los conductores.', NULL),
('cap-722efa9a70c9', 'Para transportar una cantidad de mercancías, lo fundamental es asegurarse de que el vehículo tiene capacidad para soportar ese peso. Esto se comprueba verificando que la carga útil del vehículo es superior o igual a la masa de la mercancía que se va a cargar. La carga útil es la diferencia entre la Masa Máxima Autorizada (MMA) y la tara del vehículo. No se trata de un cálculo de masa sustancial ni de simulaciones de espacio, ya que el peso es el factor limitante principal.', NULL),
('cap-723f5c8c97a7', 'El tacógrafo es una herramienta fundamental para asegurar que se cumplen los tiempos de conducción y descanso, protegiendo así la seguridad vial y las condiciones laborales de los conductores. Su objetivo principal es garantizar el cumplimiento de la normativa social en el transporte por carretera. Reducir el consumo de carburante o la contaminación son objetivos secundarios que se pueden derivar de una buena gestión, pero no son la finalidad directa del tacógrafo. Conocer la hora de llegada de las mercancías al destino es una función de la logística, no del tacógrafo.', 'Reglamento Comunitario (CE) 561/2006 Considerando'),
('cap-72662a59e69f', 'El filtro del aire es crucial porque si está sucio u obstruido, impide que llegue suficiente aire limpio al motor. Esto provoca una combustión incompleta del carburante, lo que se traduce directamente en un mayor consumo y una pérdida de potencia. Un filtro en mal estado obliga al motor a trabajar más para obtener el mismo rendimiento. El sistema de mando de la distribución no influye directamente en el consumo, ya que su función es sincronizar el movimiento de las válvulas.', NULL),
('cap-726a938960cd', 'Cuando un neumático tiene menos presión de la debida, su resistencia a la rodadura aumenta porque la superficie de contacto con el asfalto es mayor y se deforma más. Este aumento de la resistencia obliga al motor a hacer más fuerza para mover el vehículo, lo que se traduce directamente en un mayor consumo de carburante. La estabilidad del vehículo disminuye, no aumenta, y la adherencia no mejora, sino que se vuelve irregular.', NULL),
('cap-728c18d00b63', 'El sistema LKA (Lane Keeping Assist) está diseñado para mantener el vehículo dentro de su carril. Para lograrlo, el sistema interviene directamente sobre la dirección del vehículo, realizando pequeñas correcciones para evitar que se desvíe. Actuar sobre las ruedas motrices, la inyección o los retardadores no tendría sentido para la función de mantenimiento de carril.', NULL),
('cap-72a8b1f4b2f3', 'Al referirnos a la empresa en una presentación, siempre debemos usar el plural. Esto transmite una imagen de equipo y de que la empresa es un conjunto de personas, no solo una. Usar el singular puede dar la impresión de que la empresa eres solo tú o que no hay un equipo detrás.', NULL),
('cap-72c8bde37fa3', 'La base de datos de transportistas de animales debe incluir los datos de los vehículos y contenedores que se utilizan para el transporte de animales vivos. Esto es fundamental para asegurar la trazabilidad y el control de las condiciones en las que se realiza el transporte. Los ganaderos, mataderos y granjas son eslabones de la cadena, pero no son los elementos que se registran en la base de datos de transportistas.', NULL),
('cap-72ee61244a06', 'La aduana de partida es la encargada de establecer el plazo para la presentación de las mercancías en la aduana de destino, considerando factores como el itinerario y el medio de transporte. Este plazo es vinculante y no puede ser modificado por otras autoridades aduaneras. Las opciones que mencionan plazos fijos de cuatro, siete o diez días son incorrectas, ya que el plazo no es estándar, sino que se determina en cada caso particular.', 'Reglamento Comunitario (UE) 2015/2447 Art. 297'),
('cap-72f5f718010c', 'Una presión excesiva en los neumáticos reduce la superficie de contacto del neumático con la carretera, concentrando el apoyo en la parte central de la banda de rodadura. Esta menor superficie de contacto disminuye la adherencia, lo que directamente perjudica la capacidad de frenado del vehículo. Pensar que una presión alta reduce el consumo es un error, ya que la menor superficie de contacto no compensa la pérdida de adherencia y seguridad.', NULL),
('cap-72f83e49d5ef', 'La prohibición de que el conductor participe en la descarga tiene excepciones. Una de ellas es cuando la descarga se realiza por medios propios del vehículo, como ocurre con los vehículos basculantes que vierten la carga. En este caso, la acción del conductor es indispensable para operar el mecanismo de descarga del propio camión. El transporte de mercancías en contenedores no exime al conductor de la prohibición, ya que la descarga del contenedor suele requerir maquinaria externa.', NULL),
('cap-731dc82d4414', 'Un kilovatio es una unidad de potencia del Sistema Internacional, mientras que el caballo de vapor es una unidad de potencia del sistema técnico. Para convertir de kilovatios a caballos de vapor, se utiliza un factor de conversión fijo. La equivalencia correcta es que un kilovatio equivale a 1,36 caballos de vapor. Las otras opciones son incorrectas y no representan la conversión estándar entre estas unidades de potencia.', NULL),
('cap-7328ad20b6b3', 'La duración máxima de la jornada semanal para un conductor profesional es de 60 horas, tal como establece el RD 1561/1995 Art. 10 bis 1. Aunque la media semanal no puede superar las 48 horas en un periodo de cuatro meses, puntualmente se puede llegar a las 60 horas. La opción de 48 horas es la media semanal, no el máximo absoluto.', 'RD 1561/1995 Art. 10 bis 1'),
('cap-738a71a5997c', 'El sistema de sujeción indirecta se basa en aumentar la fricción entre la carga y la plataforma del vehículo, así como con las paredes, para evitar su movimiento. Esto se consigue aplicando una fuerza hacia abajo sobre la carga, que la presiona contra el suelo. El sistema de sujeción directa, por el contrario, inmoviliza la carga impidiendo físicamente su movimiento en una dirección específica.', NULL),
('cap-73a5b50f81f1', 'Encender un cigarrillo es una acción que el conductor realiza, por lo que es un factor interno que desvía su atención de la carretera. Esta distracción puede ocurrir en cualquier tipo de trayecto, no solo en los largos. No es un factor externo porque no proviene del entorno del vehículo o de la vía.', NULL),
('cap-73aa38906845', 'Los deflectores de techo reducen la resistencia aerodinámica del vehículo, lo que se traduce en un menor esfuerzo del motor para mantener la velocidad. Esta mejora en la aerodinámica puede disminuir el consumo de combustible hasta en un 6%. Otros porcentajes son demasiado altos para la mejora que aportan los deflectores.', NULL),
('cap-73e369ff8c19', 'Un accidente con lesiones genera gastos en múltiples frentes. Los tratamientos físicos y psicológicos son fundamentales para la recuperación de las víctimas. Además, pueden necesitar ayudas técnicas como sillas de ruedas o prótesis, y en casos graves, la asistencia de una tercera persona para actividades diarias. Por lo tanto, todos estos aspectos representan gastos directos para los afectados.', NULL),
('cap-73edfcbe2bb3', 'El agua es la bebida más eficaz para reponer los líquidos que se pierden con el sudor y mantener el cuerpo hidratado, especialmente en verano. Otras bebidas como el café o el alcohol tienen un efecto diurético, lo que significa que aumentan la producción de orina y pueden contribuir a la deshidratación en lugar de prevenirla. La leche caliente no es una opción adecuada para la hidratación en climas cálidos.', NULL),
('cap-7401b78404a7', 'El transporte es un motor económico que impulsa a muchos otros sectores. La fabricación de vehículos y sus componentes, la venta de los propios vehículos y el consumo de carburantes son ejemplos claros de industrias que dependen directamente de la actividad del transporte. Por eso, el efecto arrastre del transporte es muy amplio y beneficia a todos estos sectores.', NULL),
('cap-741d1cdbb024', 'El programa electrónico de estabilidad es conocido por las siglas ESP, que vienen del inglés Electronic Stability Program. Este sistema ayuda a mantener el control del vehículo en situaciones críticas, como derrapes o pérdidas de trayectoria. El ABS es otro sistema de seguridad importante, pero su función principal es evitar el bloqueo de las ruedas durante la frenada, no la estabilidad general del vehículo.', NULL),
('cap-7424ec6bc4c3', 'Si el vehículo coge velocidad en una bajada prolongada, hay que pisar el freno de servicio de forma progresiva para controlar la velocidad sin sobrecalentar los frenos. Reducir una marcha pisando el embrague en esa situación puede hacer que el motor se revolucione excesivamente o que se pierda el control. El ralentizador de emergencia no existe como tal, se usa el ralentizador o freno motor de forma anticipada y no de emergencia. El bloqueo de ruedas es una acción muy peligrosa que provocaría un derrape incontrolado.', NULL),
('cap-74575c50cbad', 'La calidad de un servicio de transporte la percibe el cliente por muchos factores. Que la carga llegue en perfecto estado es fundamental. El trato del conductor es la imagen de la empresa y el desarrollo completo del trayecto, sin interrupciones ni desvíos injustificados, también contribuye a esa percepción positiva. Por eso, todas las opciones mencionadas son correctas.', NULL),
('cap-74837b52660a', 'El tráfico pesado, al estar más ligado a la actividad económica y al transporte de mercancías, tiende a ser más constante a lo largo del día y de la semana, con menos picos y valles que el tráfico de vehículos ligeros. Esto se debe a que las operaciones de carga y descarga, así como las rutas de distribución, suelen tener horarios más regulares y predecibles. Por el contrario, el carácter turístico del tráfico o la proximidad de una gran población suelen generar mayores fluctuaciones, con aumentos significativos en fines de semana, festivos o en horas punta.', NULL),
('cap-74c49109ed34', 'El Reglamento Comunitario (UE) 165/2014 Art. 34.1 establece claramente que los conductores deben usar su tarjeta de conductor todos los días que conduzcan, a partir del momento en que se hagan cargo del vehículo. Esto asegura que todas las actividades relacionadas con el trabajo queden registradas desde el inicio. La opción de insertarla solo cuando se conduce es incorrecta porque la tarjeta debe registrar también otros trabajos, disponibilidades, pausas y descansos.', 'Reglamento Comunitario (UE) 165/2014 Art. 34.1'),
('cap-75077684750f', 'La limpieza del vehículo es crucial para evitar la contaminación cruzada entre diferentes tipos de alimentos. Si transportas el mismo tipo de alimento, no es estrictamente necesario limpiar entre cargas, pero si cambias de producto, la limpieza es obligatoria para mantener la higiene. Limpiar diariamente o semanalmente no es suficiente si se transportan alimentos distintos en el mismo día, y limpiar siempre entre carga y carga es excesivo si se repite el mismo tipo de producto.', NULL),
('cap-750c2ad53ebb', 'Portugal es uno de los países fundadores del Espacio Schengen, lo que permite la libre circulación de personas sin controles fronterizos. El Acuerdo Adhesión de la República Portuguesa al Convenio de aplicación del Acuerdo de Schengen. Art. 1 confirma su pertenencia. Países como Reino Unido, Turquía o Georgia no forman parte de este espacio de libre circulación.', 'Acuerdo Adhesión de la República Portuguesa al Convenio de aplicación del Acuerdo de Schengen. Art. 1'),
('cap-7513cb6f2c9b', 'Nunca debemos dar comida o bebida a los heridos en un accidente. Podrían necesitar una intervención quirúrgica urgente y tener el estómago vacío es crucial para evitar complicaciones. Hablar con los heridos, preguntarles su nombre o cómo se encuentran, y pararse a auxiliar son acciones correctas y necesarias para evaluar la situación y prestar ayuda.', NULL),
('cap-751a82f1e56a', 'Los efectos del alcohol son más notables cuando la concentración de alcohol en la sangre alcanza su máximo, es decir, en el pico de la curva de alcoholemia. Es en este momento cuando el organismo ha absorbido la mayor cantidad de alcohol y sus efectos sobre la capacidad de conducción son más intensos. Cuando la curva está en fase descendente, el cuerpo ya está eliminando el alcohol y los efectos empiezan a disminuir. La última consumición no garantiza el punto más elevado, ya que el alcohol tarda un tiempo en ser absorbido y alcanzar su concentración máxima en sangre.', NULL),
('cap-756726de6feb', 'El régimen ATA se utiliza para la importación temporal de mercancías, como muestras comerciales, material profesional o artículos para exposiciones, ferias o eventos similares. Permite que estas mercancías circulen entre los países firmantes del Convenio ATA sin pagar aranceles ni impuestos de importación. Es un régimen de tránsito aduanero que facilita el movimiento internacional de estos bienes por un tiempo limitado. La opción que menciona el transporte de mercancías dentro de la Unión Europea es incorrecta, ya que para eso existen otros regímenes y la UE es un territorio aduanero único.', 'Convenio ATA Art. 2'),
('cap-757fc44bb662', 'Un herido en accidente puede necesitar ayuda técnica, como sillas de ruedas o prótesis, para recuperar su autonomía. También puede requerir la ayuda de terceras personas para tareas cotidianas si sus limitaciones son severas. Además, los tratamientos físicos, como la fisioterapia, son esenciales para la rehabilitación y para mejorar su capacidad funcional. Por lo tanto, todas estas formas de ayuda son necesarias para facilitar el desarrollo de sus actividades diarias.', NULL),
('cap-758410859e13', 'El peatón tecnológico se caracteriza por tener su atención centrada en el dispositivo electrónico que está utilizando, como un teléfono móvil. Esto provoca una distracción significativa del entorno, lo que aumenta el riesgo de accidentes. No es cierto que tenga un mayor conocimiento de la normativa ni que esté más atento al tráfico; de hecho, su atención está desviada.', NULL),
('cap-759a541bf058', 'Un transporte se considera internacional si su recorrido pasa, aunque sea solo un tramo, por el territorio de otro país. No es necesario que atraviese varios países, ni que se realice íntegramente fuera de España. La Ley 16/1987 Art. 65 lo define claramente: basta con que el itinerario discurra parcialmente por el territorio de Estados extranjeros. La opción que indica que debe discurrir al menos parcialmente por el territorio de dos o tres Estados extranjeros es incorrecta, ya que con uno solo es suficiente para que se considere internacional.', 'Ley 16/1987 Art. 65'),
('cap-759f39837031', 'La función principal de un comercial es mantener la relación con el cliente, lo que incluye gestionar y responder a cualquier problema o incidencia que surja durante el servicio. Es su responsabilidad asegurar la satisfacción del cliente y la continuidad del negocio. Conducir los vehículos es tarea del conductor, no del comercial.', NULL),
('cap-75a4ba886060', 'El Reglamento Comunitario (UE) 165/2014 Art. 33.1 establece que la empresa debe entregar un número suficiente de discos-diagrama. Este número debe considerar la duración del servicio y la posibilidad de que se estropeen o sean retirados por un agente. La opción que indica que el empresario no está obligado a entregar discos es incorrecta, ya que la normativa asigna esta responsabilidad directamente a la empresa de transporte.', 'Reglamento Comunitario (UE) 165/2014 Art. 33.1'),
('cap-75bedbc441e8', 'Aunque no pises el acelerador, el motor necesita seguir girando para mantener los sistemas auxiliares del vehículo, como la dirección asistida o el alternador. Para ello, la centralita inyecta una pequeña cantidad de combustible, la justa para que el motor no se cale y se mantenga al ralentí. Por lo tanto, el consumo no es nulo en esta situación. El consumo no será mayor cuanto mayor sea la velocidad del vehículo, ya que el motor está desacoplado de las ruedas.', NULL),
('cap-75c25f358360', 'La declaración amistosa de accidente es un documento para recoger toda la información relevante del siniestro. Incluir las observaciones de los conductores permite añadir detalles que pueden ser importantes para entender lo ocurrido. Esto ayuda a las aseguradoras a tener una visión más completa del accidente. La idea de que solo se pueden añadir observaciones si hay heridos es incorrecta, ya que el objetivo es documentar el suceso lo más fielmente posible.', NULL),
('cap-75d6f3dff3b3', 'Los 30 metros son la distancia mínima de seguridad para alejar a los pasajeros de un autobús en caso de evacuación. Esta distancia permite protegerlos de posibles riesgos como explosiones o incendios, a la vez que facilita el trabajo de los servicios de emergencia. Alejar a los pasajeros 100 metros o más es excesivo y puede dificultar la gestión de la emergencia, mientras que 50 metros podría ser insuficiente en ciertas situaciones.', NULL),
('cap-75d7a8ac94c2', 'Las autorizaciones bilaterales de transporte internacional se conceden para un periodo de tiempo determinado, que puede ser para un solo viaje o para un periodo más largo, como un año. Por eso, pueden ser temporales o de un viaje. Decir que solo pueden ser temporales o solo de un viaje es incorrecto porque no abarca todas las posibilidades. La opción de cinco años es incorrecta porque esa duración no es una característica definitoria de las autorizaciones bilaterales.', NULL),
('cap-75ead20aea9b', 'Las Juntas Arbitrales del Transporte pueden acordar el depósito de mercancías en varias situaciones. Una es cuando el transportista retiene la mercancía porque no le pagan el precio del transporte. También pueden acordarlo si hay impedimentos para entregar la mercancía en las condiciones pactadas y el cargador no da nuevas instrucciones. Finalmente, también es posible si hay impedimentos para realizar el transporte en las condiciones acordadas y el cargador no da nuevas instrucciones. Por lo tanto, todas las situaciones descritas son correctas.', NULL),
('cap-75f75f02912d', 'La carta de porte en un transporte CMR debe incluir la naturaleza de la mercancía para identificarla correctamente. Es un dato fundamental para el transportista y para cualquier control. El Convenio CMR Art. 6 establece claramente qué indicaciones son obligatorias. El número de bultos o paquetes que componen la carga no es una indicación obligatoria, aunque pueda ser útil.', 'Convenio CMR Art. 6'),
('cap-76146b69e90b', 'El tiempo de trabajo de un conductor autónomo se refiere a las actividades directamente relacionadas con una operación de transporte, como la conducción, carga, descarga o asistencia a pasajeros. Las tareas administrativas generales que no están vinculadas a un transporte específico no se consideran tiempo de trabajo. Esto se debe a que son actividades de gestión del negocio que no implican la ejecución de un servicio de transporte. Confundir estas tareas con el tiempo de trabajo es un error común, pero la normativa es clara al respecto.', NULL),
('cap-7622f28e61e1', 'Una autorización CEMT permite realizar un número ilimitado de viajes durante su periodo de validez, que suele ser un año natural. Su propósito es facilitar el transporte internacional de mercancías por carretera entre los países miembros de la CEMT sin necesidad de permisos adicionales por cada viaje. Las autorizaciones CEMT no establecen un tope en la cantidad de trayectos que se pueden efectuar. Confundir esto con un número limitado de viajes es un error común, ya que algunas autorizaciones bilaterales sí pueden tener restricciones de este tipo.', NULL),
('cap-763823cce739', 'El consumo de combustible es directamente proporcional al trabajo que realiza el motor. Para alcanzar la máxima potencia, el motor necesita quemar la mayor cantidad de combustible posible en un momento dado. Por lo tanto, cuando el motor está entregando su máxima potencia, es cuando más combustible está gastando. Un par bajo no implica necesariamente un alto consumo, ya que el motor puede estar girando a bajas revoluciones.', NULL),
('cap-7666a458f216', 'El agua es la materia más utilizada para extinguir incendios por enfriamiento porque absorbe una gran cantidad de calor al evaporarse, reduciendo rápidamente la temperatura del combustible por debajo de su punto de ignición. El oxígeno, por el contrario, es un comburente que alimenta el fuego, no lo extingue.', NULL),
('cap-7688c20896c5', 'Es fundamental dejar que el cliente exprese completamente su necesidad o problema para entenderlo bien y poder ofrecer la mejor solución. Interrumpir al cliente puede generar frustración y la sensación de que no se le está escuchando. Contestar apresuradamente o distraerse mientras habla el cliente son errores que impiden una comunicación efectiva y profesional.', NULL),
('cap-76a03efd9723', 'Cuando un neumático tiene menos presión de la debida, aumenta la superficie de contacto con el suelo y, por tanto, la resistencia a la rodadura. Esto hace que el motor tenga que esforzarse más para mover el vehículo, lo que se traduce en un mayor consumo de carburante. Por lo tanto, es falso que disminuya la cantidad de carburante necesaria. La inestabilidad y la menor adherencia son consecuencias reales de una presión baja.', NULL),
('cap-76c36e32c973', 'El ABS evita que las ruedas se bloqueen, permitiendo mantener el control de la dirección durante la frenada. En superficies mojadas, esto se traduce en una reducción de la distancia de frenado al optimizar la adherencia. En seco, la mejora es menor, y en superficies muy sueltas como grava o nieve, el bloqueo de la rueda puede incluso ayudar a acumular material delante de ella, lo que el ABS impide, pudiendo alargar la distancia.', NULL),
('cap-76c743fc5cdf', 'La temperatura en el puesto de conducción afecta al rendimiento del conductor en cualquier momento del día o de la noche. Mantener una temperatura adecuada es crucial para la concentración y para evitar la fatiga, lo que mejora la seguridad. No es un factor que solo importe de día o de noche, sino una constante para el bienestar del conductor. La idea de que solo importa en un horario específico es incorrecta, ya que el cuerpo humano necesita una temperatura estable para funcionar óptimamente siempre.', NULL),
('cap-7704dae862ef', 'La zona de menor consumo en el cuentarrevoluciones se determina por la eficiencia del motor, que está directamente relacionada con el consumo específico, la potencia y el par motor máximo. Estos factores indican a qué revoluciones el motor trabaja de forma más eficiente, gastando menos combustible. El tipo de frenos, ya sean de disco o de tambor, no tiene ninguna relación con el rendimiento del motor ni con su consumo de combustible. Los frenos solo sirven para detener el vehículo, no para optimizar el consumo.', NULL),
('cap-77334a07f09e', 'El sistema ABS está diseñado precisamente para evitar el bloqueo de las ruedas en situaciones de baja adherencia, como ocurre con el hielo. Su función es modular la presión de frenado para que la rueda siga girando, aunque sea lentamente, manteniendo así la capacidad de dirección. La afirmación de que el ABS solo funciona con calzada seca es incorrecta, ya que su principal utilidad se manifiesta en condiciones adversas.', NULL),
('cap-77363c733034', 'Permanecer sentado e inmovilizado durante periodos prolongados es un factor de riesgo importante en el transporte. Esta postura puede provocar problemas musculoesqueléticos, circulatorios y fatiga. Es crucial que los conductores sean conscientes de estos riesgos para prevenirlos. La idea de que solo afecta a un porcentaje bajo de casos es incorrecta, ya que es un riesgo generalizado en la profesión.', NULL),
('cap-77656fadd5e9', 'Si el filtro del aire está sucio, el motor no recibe suficiente aire limpio para la combustión. Para compensar la falta de aire, la centralita inyecta más carburante, lo que provoca un aumento del consumo. La opción de que aumentaría excesivamente la potencia del motor es incorrecta, ya que la falta de aire y el exceso de carburante en realidad reducirían la potencia.', NULL),
('cap-7784328d0155', 'El masaje cardiaco por sí solo no es suficiente; hay que combinarlo con la respiración boca a boca para que el herido reciba oxígeno y la sangre oxigenada circule. Las palmaditas en la cara, los golpes en la nuca o los masajes en el brazo no tienen ninguna utilidad en una parada cardiorrespiratoria y solo harían perder un tiempo precioso.', NULL),
('cap-77c44533c706', 'Encender un cigarrillo mientras conduces desvía tu atención de la carretera y del tráfico, lo que lo convierte en una distracción. Cualquier acción que te aparte de la tarea principal de conducir aumenta el riesgo de accidente. No es una decisión alternativa, ya que no resuelve un problema de conducción, y tampoco forma parte de la información del entorno, que es lo que te rodea en la vía.', NULL),
('cap-77f6c45ade66', 'El Reglamento Comunitario (UE) 952/2013 Art. 226 establece que el tránsito externo puede realizarse de varias maneras. Entre ellas se incluyen el régimen de tránsito externo de la Unión, el Convenio TIR y el Convenio ATA. Por lo tanto, todas las opciones mencionadas son sistemas de tránsito aduanero válidos en la Unión Europea.', 'Reglamento Comunitario (UE) 952/2013 Art. 226')
) as v(id, explicacion, norma)
where preguntas.id = v.id::text;
